"""Every case in conformance/routing.v1.json, generated by the TypeScript reference."""

import json
import unittest
from pathlib import Path

from super_router import RouterError, route

CASES = json.loads((Path(__file__).resolve().parents[3] / "conformance" / "routing.v1.json").read_text())["route"]


def run(service, invocation):
    try:
        candidates, excluded = route(service, invocation)
    except RouterError as e:
        return {"error": e.code}
    return {
        "ok": {
            "candidates": [{"id": c.offering["id"], "cost": str(c.cost), "score": c.score} for c in candidates],
            "excluded": excluded,
        }
    }


class RoutingConformance(unittest.TestCase):
    def test_every_case(self):
        self.assertGreaterEqual(len(CASES), 300)
        for i, case in enumerate(CASES):
            with self.subTest(i=i):
                self.assertEqual(run(case["service"], case["invocation"]), case["expect"])

    def test_coverage(self):
        withc = sum(1 for c in CASES if c["expect"].get("ok", {}).get("candidates"))
        errors = sum(1 for c in CASES if "error" in c["expect"])
        self.assertGreaterEqual(withc, 100)
        self.assertGreaterEqual(errors, 1)


if __name__ == "__main__":
    unittest.main()
